language "moriarty-sherlock-nominal/1";
program P {
  type Schedule { Done; Pay(a_amount: UInt, b_next: Schedule); Both(a_left: Schedule, b_right: Schedule); }
  fn pick(s: Schedule): UInt {
    match s {
      Schedule::Both(Schedule::Pay(x, y), z) => x,
      Schedule::Both(q, r) => total(r),
      Schedule::Pay(x, t) => x + total(t),
      Schedule::Done() => 0
    }
  }
  fn total(s: Schedule): UInt {
    match s {
      Schedule::Done() => 0,
      Schedule::Pay(x, t) => x + total(t),
      Schedule::Both(l, r) => total(l) + total(r)
    }
  }
  entry pick(construct Schedule::Both(construct Schedule::Pay(4, construct Schedule::Done()), construct Schedule::Pay(5, construct Schedule::Done())));
}

